-- Hand-written migration (not generated by `prisma migrate dev`): a plain
-- diff would DROP the DRAFT/ACTIVE enum values and recreate the type,
-- destroying every existing Study's status. RENAME VALUE preserves it.
ALTER TYPE "StudyStatus" RENAME VALUE 'DRAFT' TO 'PROPOSED';
ALTER TYPE "StudyStatus" RENAME VALUE 'ACTIVE' TO 'CONFIRMED_SOLD';

